            (1, False, "2.3. N/D BOP stack - inspect rams and seals, store properly."),
            (1, False, "2.4. Lay down drill string - rack back on pipe racks."),
            (1, False, "2.5. Drain and rig down mud system, clean pits."),
            (1, False, "2.6. Lower and section mast/derrick per manufacturer procedure."),
            (1, False, "2.7. Disconnect substructure for transport."),
            (1, False, "2.8. Disconnect power generation and fuel systems."),
            (1, False, "2.9. Document final rig condition and inventory."),
            (0, True, "3. TRANSPORT"),
            (1, False, "3.1. Load equipment per transport plan and load charts."),
            (1, False, "3.2. Secure all loads with chains, binders, and flags."),
            (1, False, "3.3. Conduct pre-transport safety check on each load."),
            (1, False, "3.4. Transport with escorts per approved route."),
            (1, False, "3.5. Unload at destination in correct rig-up sequence."),
            (0, True, "4. RIG UP AT NEW LOCATION"),
            (1, False, "4.1. Position and level substructure (±0.5° tolerance)."),
            (1, False, "4.2. Verify substructure alignment with cellar/conductor."),
            (1, False, "4.3. Raise and pin mast/derrick per manufacturer procedure."),
            (1, False, "4.4. Install crown block, traveling block, and hook."),
