            (1, False, "2.6. Any discrepancy > {max_discrepancy} bbl shall be investigated."),
            (1, False, "2.7. Maximum trip speed: per program."),
            (1, False, "2.8. Monitor for swabbing indicators:"),
            (2, False, "a) Watch for unexpected pit level increase"),
            (2, False, "b) Well not taking correct fill volume"),
            (2, False, "c) Returns while pumps off"),
            (0, True, "3. OVERPULL MANAGEMENT"),
            (1, False, "3.1. If overpull < {max_drag} kips: reciprocate string and try to pass."),
            (1, False, "3.2. If unable to pass: try with pump out (circulation while POOH)."),
            (1, False, "3.3. If overpull > {max_drag} kips:"),
