            (0, True, "2. PREPARATION"),
            (1, False, "2.1. Circulate bottoms up at TD. Monitor returns for clean hole."),
            (1, False, "2.2. Pump {pill_volume} bbl Hi-Vis pill. Circulate till shaker clean."),
            (1, False, "2.3. Record off-bottom parameters (SPP, torque, weight)."),
            (1, False, "2.4. Prepare trip sheet."),
            (1, False, "2.5. Line up trip tank."),
