            (1, False, "5.10. The 5 bbl cement pumped after plug is considered in displacement volume."),
            (1, False, "5.11. Take rig pumps efficiency before cement job."),
            (1, False, "5.12. All rig pumps must be serviced and ready for operation."),
            (0, True, "6. MONITORING DURING PUMPING"),
            (1, False, "6.1. Monitor surface pressure continuously. Do NOT exceed {max_pressure} psi."),
            (1, False, "6.2. Do NOT exceed 80% of burst rating of weakest part of casing.", False, True),
            (1, False, "6.3. Monitor ECD (if PWD available) - do NOT exceed fracture gradient."),
