            (1, False, "6.10. All senior personnel present during cement job."),
            (0, True, "7. PLUG BUMP"),
            (1, False, "7.1. Bump plug with final circulating pressure."),
            (1, False, "7.2. Increase pressure in increments to {bump_pressure} psi (Green Test)."),
