            (1, False, "7.4. Check back flow from cement unit."),
            (1, False, "7.5. If abnormal return: close valve of cement head, monitor pressure."),
            (1, False, "7.6. If plug does NOT bump after calculated displacement:"),
            (2, False, "Continue with {extra_displacement} of shoe track volume"),
            (1, False, "7.7. Only time casing can be pressure tested is after bumping while cement is liquid."),
            (1, False, "7.8. No pressure test after cement starts to set (micro-channels risk).", False, True),
            (0, True, "8. WAIT ON CEMENT (WOC)"),
            (1, False, "8.1. Open side outlet valve of CHS. Flush and clean side outlet and diverter."),
