            (1, False, "8.3. Do NOT install handy slips around casing string during WOC."),
            (1, False, "8.4. Keep string weight on elevator till surface samples get hard."),
            (1, False, "8.5. Monitor casing pressure during WOC."),
            (1, False, "8.6. Do NOT disturb casing during WOC."),
            (0, True, "9. POST-CEMENT"),
