# ============================================================================
# MAIN EXECUTION
# ============================================================================

if __name__ == "__main__":
    print()
    print("=" * 70)
    print("  🛢️  DRILLING PROCEDURES DATABASE - COMPLETE SEED V3")
    print("  Professional Procedures with Variable Inputs")
    print("  Based on: W014N, Azar-05/08/18, PowerPak, Milling Manual,")
    print("            Well Control Theory, DST HSE, API RP 53/59,")
    print("            Shell DEP, Saudi Aramco SAES, NORSOK D-010")
    print("=" * 70)

    # Initialize database
    db = ProcedureDatabase()

    # Get stats before
    stats_before = db.get_stats()
    print(f"\n  📊 Before seeding:")
    print(f"     Procedures:      {stats_before['total_procedures']}")
    print(f"     Categories:      {stats_before['categories']}")
    print(f"     Steps:           {stats_before['total_steps']}")
    print(f"     Checklist items: {stats_before['total_checklist_items']}")

    # Run seeding
    print(f"\n  ⏳ Seeding procedures...")
    count = seed_all_v2(db)

    # Get stats after
    stats_after = db.get_stats()
    print(f"\n  ✅ Seeding complete!")
    print(f"\n  📊 After seeding:")
    print(f"     Procedures:      {stats_after['total_procedures']} "
          f"(+{stats_after['total_procedures'] - stats_before['total_procedures']})")
    print(f"     Categories:      {stats_after['categories']}")
    print(f"     Steps:           {stats_after['total_steps']} "
          f"(+{stats_after['total_steps'] - stats_before['total_steps']})")
    print(f"     Checklist items: {stats_after['total_checklist_items']} "
          f"(+{stats_after['total_checklist_items'] - stats_before['total_checklist_items']})")
    print(f"     Built-in:        {stats_after['builtin']}")
    print(f"     Custom:          {stats_after['custom']}")

    # List all procedures by category
    print(f"\n  📋 All Procedures by Category:")
    print(f"  {'─' * 60}")

    categories = db.get_all_categories()
    all_procs = db.get_all_procedures(active_only=True)

    # Group by category
    grouped = {}
    for p in all_procs:
        cat = p.category_name or "Uncategorized"
        if cat not in grouped:
            grouped[cat] = []
        grouped[cat].append(p)

    for c in categories:
        procs = grouped.get(c.name, [])
        if procs:
            print(f"\n  {c.icon} {c.name} ({len(procs)} procedures)")
            for p in procs:
                # Count steps and checklist
                steps = db.get_steps(p.id)
                checklist = db.get_checklist(p.id)
                inputs = db.get_inputs(p.id)
                icon = "⭐" if p.is_builtin else "📝"
                print(f"     {icon} {p.name}")
                print(f"        Steps: {len(steps)} | "
                      f"Checklist: {len(checklist)} | "
                      f"Inputs: {len(inputs)}")

    # Summary
    total_inputs = 0
    for p in all_procs:
        inputs = db.get_inputs(p.id)
        total_inputs += len(inputs)

    print(f"\n  {'═' * 60}")
    print(f"  📊 FINAL SUMMARY:")
    print(f"  {'─' * 60}")
    print(f"  Total Procedures:       {stats_after['total_procedures']}")
    print(f"  Total Categories:       {stats_after['categories']}")
    print(f"  Total Steps:            {stats_after['total_steps']}")
    print(f"  Total Checklist Items:  {stats_after['total_checklist_items']}")
    print(f"  Total Variable Inputs:  {total_inputs}")
    print(f"  {'─' * 60}")
    print(f"  All procedures have:")
    print(f"    ✅ Detailed step-by-step instructions")
    print(f"    ✅ Pre-job checklists with categories")
    print(f"    ✅ Variable inputs (adjustable parameters)")
    print(f"    ✅ Safety warnings and critical notes")
    print(f"    ✅ Based on real field procedures and standards")
    print(f"  {'═' * 60}")

    # Close database
    db.close()

    print(f"\n  ✅ Database saved successfully!")
    print(f"  📁 Location: ~/.drilling_program/procedures.db")
    print(f"\n  🚀 To use:")
    print(f"     1. Run main.py (GUI application)")
    print(f"     2. Go to: Procedures → Procedure Manager")
    print(f"     3. Select procedures and generate Word document")
    print(f"\n  Or run directly:")
    print(f"     python launcher.py")
    print(f"\n{'=' * 70}")